local BaseEffect = import('Game.Chapter.NewChapterEffect.BaseEffect')
local base = BaseEffect
local DebrisEffectHelper = CS.DebrisEffectHelper
local KTool = CS.Engine.Lib.KTool

---@class ScreenDebrisEffect : BaseEffect
local ScreenDebrisEffect = Class("ScreenDebrisEffect", BaseEffect)

local NewChapterConstants = import("Game.Chapter.NewChapterConstants")


function ScreenDebrisEffect:__init()
    
end

function ScreenDebrisEffect:__delete()
end

---@param parameters NewChapter2DVo
function ScreenDebrisEffect:Initialize(parameters)
    base.StartEffect(self, parameters)
    self.isBig = parameters.screenAnim == NewChapterConstants.ScreenEffect.BigDebris
end

function ScreenDebrisEffect:StartEffect(object)
    base.StartEffect(self, object)
    local effect = object.gameObject:GetComponent(typeof(DebrisEffectHelper))
    if isNull(effect) then
        return
    end
    effect.enabled = true
    effect.isBigRain = self.isBig
end

function ScreenDebrisEffect:IsFinish()
    base.IsFinish(self)
    return true
end

function ScreenDebrisEffect:EndEffect(object)
    base.EndEffect(self, object)
    
end

function ScreenDebrisEffect:RemoveEffect(object)
    base.RemoveEffect(self, object)
    local effect = object.gameObject:GetComponent(typeof(DebrisEffectHelper))
    if isNull(effect) then
        return
    end
    effect.enabled = false
    local trans = effect.transform:Find("Rain")
    if not isNull(trans) then
        trans = trans.gameObject
    end
    KTool.SafeDelete(trans)
end

return ScreenDebrisEffect